function isTaskFinal(status) {
  return status === 'DONE' || status === 'FAILED' || status === 'CANCELLED';
}

function isTaskActive(status) {
  if (!status) return false;
  if (isTaskFinal(status)) return false;
  if (status === 'WAITING_HUMAN') return false;
  return true;
}

